/*
 * Keep the programmable contract alive without killing the pump.
 *
 * A PPS source re-applies its output voltage on every Request, and that step is
 * enough to drive the 2:1 pump's output above its input for an instant.  The
 * chip then latches REVBLK and clears CHG_ON by itself, so the keep-alive used
 * to end direct charging every couple of seconds and hand the battery back to
 * the 9 V switching charger until the retry.  Park the pump across the
 * re-negotiation and re-arm it once the bus has settled again -- the same rule
 * sm5440_start() applies to the first contract.
 */
static int sm5440_renegotiate_pps(struct sm5440_direct *sm)
{
	int ret;

	ret = sm5440_pump_off(sm);
	if (ret)
		return ret;

	ret = sm5440_refresh_pps(sm);
	if (ret)
		return ret;

	ret = sm5440_wait_vbus_settled(sm, sm->target_mv);
	if (ret)
		return ret;

	return sm5440_pump_on(sm);
}

static int tcpm_aug_set_op_curr(struct tcpm_port *port, u16 req_op_curr_ma)
{
	unsigned int target_mw;
	int ret;

	mutex_lock(&port->swap_lock);
	mutex_lock(&port->lock);

	if (port->pps_data.active) {
		req_op_curr_ma = req_op_curr_ma -
				 (req_op_curr_ma % RDO_PROG_CURR_MA_STEP);
		if (req_op_curr_ma > port->pps_data.max_curr) {
			ret = -EINVAL;
			goto port_unlock;
		}
		target_mw = (req_op_curr_ma * port->supply_voltage) / 1000;
		if (target_mw < port->operating_snk_mw) {
			ret = -EINVAL;
			goto port_unlock;
		}
	} else if (!port->spr_avs_data.active) {
		ret = -EOPNOTSUPP;
		goto port_unlock;
	}

	if (port->state != SNK_READY) {
		ret = -EAGAIN;
		goto port_unlock;
	}

	if (port->pps_data.active)
		port->upcoming_state = SNK_NEGOTIATE_PPS_CAPABILITIES;
	else
		port->upcoming_state = SNK_NEGOTIATE_SPR_AVS_CAPABILITIES;

	ret = tcpm_ams_start(port, POWER_NEGOTIATION);
	if (ret == -EAGAIN) {
		port->upcoming_state = INVALID_STATE;
		goto port_unlock;
	}

	reinit_completion(&port->aug_supply_req_complete);
	if (port->pps_data.active)
		port->pps_data.req_op_curr = req_op_curr_ma;
	else
		port->spr_avs_data.req_op_curr_ma = req_op_curr_ma;
	port->aug_supply_req_status = 0;
	port->aug_supply_req_pending = true;
	mutex_unlock(&port->lock);

	if (!wait_for_completion_timeout(&port->aug_supply_req_complete,
					 msecs_to_jiffies(PD_AUG_PSY_CTRL_TIMEOUT)))
		ret = -ETIMEDOUT;
	else
		ret = port->aug_supply_req_status;

	goto swap_unlock;

port_unlock:
	mutex_unlock(&port->lock);
swap_unlock:
	mutex_unlock(&port->swap_lock);

	return ret;
}

static int tcpm_aug_set_out_volt(struct tcpm_port *port, u16 req_out_volt_mv)
{
	unsigned int target_mw;
	int ret;

	mutex_lock(&port->swap_lock);
	mutex_lock(&port->lock);

	if (port->pps_data.active) {
		req_out_volt_mv = req_out_volt_mv - (req_out_volt_mv %
						     RDO_PROG_VOLT_MV_STEP);
		/* Round down output voltage to align with PPS valid steps */
		target_mw = (port->current_limit * req_out_volt_mv) / 1000;
		if (target_mw < port->operating_snk_mw) {
			ret = -EINVAL;
			goto port_unlock;
		}
	} else if (!port->spr_avs_data.active) {
		ret = -EOPNOTSUPP;
		goto port_unlock;
	}

	if (port->state != SNK_READY) {
		ret = -EAGAIN;
		goto port_unlock;
	}

	if (port->pps_data.active)
		port->upcoming_state = SNK_NEGOTIATE_PPS_CAPABILITIES;
	else
		port->upcoming_state = SNK_NEGOTIATE_SPR_AVS_CAPABILITIES;

	ret = tcpm_ams_start(port, POWER_NEGOTIATION);
	if (ret == -EAGAIN) {
		port->upcoming_state = INVALID_STATE;
		goto port_unlock;
	}

	reinit_completion(&port->aug_supply_req_complete);
	if (port->pps_data.active)
		port->pps_data.req_out_volt = req_out_volt_mv;
	else
		port->spr_avs_data.req_out_volt_mv = req_out_volt_mv;
	port->aug_supply_req_status = 0;
	port->aug_supply_req_pending = true;
	mutex_unlock(&port->lock);

	if (!wait_for_completion_timeout(&port->aug_supply_req_complete,
					 msecs_to_jiffies(PD_AUG_PSY_CTRL_TIMEOUT)))
		ret = -ETIMEDOUT;
	else
		ret = port->aug_supply_req_status;

	goto swap_unlock;

port_unlock:
	mutex_unlock(&port->lock);
swap_unlock:
	mutex_unlock(&port->swap_lock);

	return ret;
}

